nodes.type:
∀ {ι : Type u_2} {κ : Type u_3} {α : Type u_1} {β : Type u_4} {D : VaughtConjecture.CellScheme ι α}
  {E : VaughtConjecture.CellScheme κ β} {φ : κ → ι},
  E.IsLowerEmbedding D φ → ∀ (s : κ) (t : ↑(E.below (E.gradedIndex s))), D.gradedIndex (φ ↑t) ≤ D.gradedIndex (φ s)

nodes.value:
fun {ι} {α} {β} D f =>
  { ground := D.ground.preimage ⇑f ⋯, faces := D.faces.preimage (Finset.map f) ⋯,
    scope := fun d => (D.scope ↑d).preimage ⇑f ⋯, grade := fun d => D.grade ↑d }

fun {n} S k M =>
  { ground := S.toCellScheme.ground, faces := S.toCellScheme.faces,
    scope := Fin.append S.toCellScheme.scope fun x => Finset.univ, grade := Fin.append S.toCellScheme.grade fun x => k }

fun {n m} S f =>
  { card := (S.visibleCells f).card, toCellScheme := (S.toCellScheme.comap f).reindex ⇑(S.cellEquiv f),
    rows := S.rows.comap ⋯ }

fun {α} {n m} t f hf =>
  let __Scheme := t.comap f;
  { toScheme := __Scheme, label := fun i => t.label ((t.cellMap f) i), isWellFormed := ⋯, isCoded := ⋯, isLawful := ⋯,
    atStage := ⋯ }
